#!/usr/bin/env node
// scaffold-enum-sync.js — v78 copy backend enum .ts files to frontend
// `app/enums/<name>.enum.ts`. Lets us preserve enum type safety on the FE
// instead of normalizing to string in scaffold-api-client-types.
//
// Source: walks backend/src/common/enums/*.enum.ts AND
// backend/src/**/*.enum.ts (LLM sometimes scatters enums by module).
// Output: app/enums/<base>.enum.ts in the FE, only if not already present
// or if the existing file is marker-managed.
//
// Idempotent. Marker: '// Generated by scaffold-enum-sync'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--backend-dir') out.backendDir = argv[++i];
    else if (a === '--target') out.target = argv[++i];
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--force') out.force = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.backendDir || !out.target) {
    console.error('Usage: scaffold-enum-sync --backend-dir BACKEND --target FRONTEND [--force]');
    process.exit(1);
  }
  return out;
}

function walk(dir, filterFn, out) {
  out = out || [];
  if (!fs.existsSync(dir)) return out;
  fs.readdirSync(dir, { withFileTypes: true }).forEach(function (e) {
    var f = path.join(dir, e.name);
    if (e.isDirectory()) {
      // Skip node_modules + dist + test
      if (/^(node_modules|dist|\.git|coverage|test|__tests__)$/.test(e.name)) return;
      walk(f, filterFn, out);
    } else if (e.isFile() && filterFn(f)) out.push(f);
  });
  return out;
}

function findEnumFiles(backendDir) {
  return walk(path.join(backendDir, 'src'), function (f) { return /\.enum\.ts$/.test(f); }, []);
}

function generatedMarker() {
  return '// Generated by scaffold-enum-sync — DO NOT EDIT BY HAND. Re-run if backend enum changes.';
}

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-enum-sync/.test(existing) && !force) {
      return { written: false, reason: 'exists-handauthored' };
    }
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

function main() {
  var args = parseArgs(process.argv);
  var enums = findEnumFiles(args.backendDir);
  if (enums.length === 0) {
    console.log('scaffold-enum-sync: no .enum.ts files under ' + args.backendDir + '/src');
    return;
  }
  var enumsDir = path.join(args.target, 'app/enums');
  var written = 0, skipped = 0, deduped = 0;
  // Dedup by basename — multiple backend modules sometimes re-define same enum
  var seen = {};
  enums.forEach(function (src) {
    var base = path.basename(src); // e.g. role.enum.ts
    if (seen[base]) { deduped++; return; }
    seen[base] = src;
    var content = fs.readFileSync(src, 'utf-8');
    // Strip cross-file imports — FE enums should be self-contained
    var stripped = content
      .split('\n')
      .filter(function (line) { return !/^\s*import\s+/.test(line); })
      .join('\n');
    var out = generatedMarker() + '\n\n' + stripped.trim() + '\n';
    var dst = path.join(enumsDir, base);
    var r = writeIfManaged(dst, out, args.force, args.dryRun);
    if (r.written) written++; else skipped++;
    if (args.verbose) console.log('  ' + base + ': ' + (r.written ? 'wrote' : r.reason));
  });
  console.log('scaffold-enum-sync: ' + written + ' written, ' + skipped + ' skipped (handauthored/unchanged), ' + deduped + ' duplicates');
}

main();
